-- SGDAI - Import Nature Économique (NBE 2019)
-- Converti depuis SQL Server (UTF-16) vers PostgreSQL
-- Date : 2026-04-15
-- Lignes : 1072
-- Usage :
--   BD locale  : psql -d <db_locale> -f db/nature_economique_import.sql
--   BD distante: psql "postgresql://sgdai_db_user:***@dpg-...frankfurt-postgres.render.com/sgdai_db" -f db/nature_economique_import.sql
-- ============================================================

BEGIN;

-- Supprime la contrainte d'unicité si elle existe encore
ALTER TABLE natures_economiques DROP CONSTRAINT IF EXISTS uq_natures_economiques_code_exercice;

-- Supprime toutes les entrées existantes + cascades FK automatiquement
TRUNCATE natures_economiques CASCADE;


-- Rattache toutes les natures économiques à l'exercice actif
UPDATE natures_economiques
SET exercice_id = (SELECT id FROM exercices WHERE actif = TRUE ORDER BY annee DESC LIMIT 1)
WHERE exercice_id IS NULL;

COMMIT;

